import type { IsoTimestamp, OrgId, UserId } from "./common";

/** What an API token is allowed to do on behalf of its owner. */
export type ApiTokenScope = "read" | "write";

/**
 * A personal API token. The secret and its hash never appear on this value —
 * the secret is returned once from `createApiToken`, and only the hash is stored.
 */
export interface ApiToken {
  readonly id: string;
  readonly orgId: OrgId;
  readonly userId: UserId;
  readonly name: string;
  readonly scope: ApiTokenScope;
  readonly prefix: string;
  readonly expiresAt: IsoTimestamp;
  readonly lastUsedAt: IsoTimestamp | null;
  readonly revokedAt: IsoTimestamp | null;
  readonly createdAt: IsoTimestamp;
}

import { z } from "zod";
import { orgIdSchema } from "./common";

export const createApiTokenSchema = z.object({
  orgId: orgIdSchema,
  name: z.string().trim().min(1).max(80),
  scope: z.enum(["read", "write"]),
  expiresInDays: z.number().int().min(1).max(365),
});

export type CreateApiTokenInput = z.input<typeof createApiTokenSchema>;

import { index, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns, timestampColumns } from "./_shared";

export const apiTokens = sqliteTable(
  "api_tokens",
  {
    id: idColumn(),
    ...tenantColumns,
    userId: text("user_id").notNull(),
    name: text("name").notNull(),
    scope: text("scope", { enum: ["read", "write"] }).notNull(),
    tokenHash: text("token_hash").notNull(),
    prefix: text("prefix").notNull(),
    expiresAt: text("expires_at").notNull(),
    lastUsedAt: text("last_used_at"),
    revokedAt: text("revoked_at"),
    ...timestampColumns,
  },
  (table) => [
    uniqueIndex("api_tokens_hash_idx").on(table.tokenHash),
    index("api_tokens_org_user_idx").on(table.orgId, table.userId),
  ],
);

export type ApiTokenRow = typeof apiTokens.$inferSelect;

