/**
 * Personal API tokens. Stores the hash of the secret, never the secret itself.
 */
import { and, count, desc, eq, gt, isNull } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, apiTokens } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { brandId, brandStamp, brandStampOrNull } from "./_mappers";
import type { ApiTokenRow } from "@/server/db/schema/api-tokens";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { ApiToken, ApiTokenScope } from "@/types/api-token";

export type NewApiTokenRow = {
  orgId: OrgId;
  userId: UserId;
  name: string;
  scope: ApiTokenScope;
  tokenHash: string;
  prefix: string;
  expiresAt: IsoTimestamp;
  createdAt: IsoTimestamp;
};

function toApiToken(row: ApiTokenRow): ApiToken {
  return {
    id: row.id,
    orgId: brandId<OrgId>(row.orgId),
    userId: brandId<UserId>(row.userId),
    name: row.name,
    scope: row.scope,
    prefix: row.prefix,
    expiresAt: brandStamp(row.expiresAt),
    lastUsedAt: brandStampOrNull(row.lastUsedAt),
    revokedAt: brandStampOrNull(row.revokedAt),
    createdAt: brandStamp(row.createdAt),
  };
}

export async function insertApiToken(input: NewApiTokenRow): Promise<ApiToken> {
  const row = getDb()
    .insert(apiTokens)
    .values({
      id: newId(),
      orgId: input.orgId,
      userId: input.userId,
      name: input.name,
      scope: input.scope,
      tokenHash: input.tokenHash,
      prefix: input.prefix,
      expiresAt: input.expiresAt,
      lastUsedAt: null,
      revokedAt: null,
      createdAt: input.createdAt,
      updatedAt: input.createdAt,
    })
    .returning()
    .get();
  return toApiToken(row);
}

export async function listApiTokensForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.userId, userId)))
    .orderBy(desc(apiTokens.createdAt), desc(apiTokens.id))
    .all();
  return rows.map(toApiToken);
}

/** Tokens that still count against the per-user cap: not revoked and not expired. */
export async function countUsableApiTokens(
  orgId: OrgId,
  userId: UserId,
  now: IsoTimestamp,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(apiTokens)
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
        isNull(apiTokens.revokedAt),
        gt(apiTokens.expiresAt, now),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function findApiTokenById(
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .get();
  return row ? toApiToken(row) : null;
}

export async function findApiTokenByHash(
  tokenHash: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(eq(apiTokens.tokenHash, tokenHash))
    .get();
  return row ? toApiToken(row) : null;
}

export async function listUnrevokedApiTokens(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .select()
    .from(apiTokens)
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .all();
  return rows.map(toApiToken);
}

export async function revokeApiTokenRow(
  orgId: OrgId,
  tokenId: string,
  revokedAt: IsoTimestamp,
): Promise<ApiToken | null> {
  const row = getDb()
    .update(apiTokens)
    .set({ revokedAt, updatedAt: revokedAt })
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .returning()
    .get();
  return row ? toApiToken(row) : null;
}

export async function touchApiTokenLastUsed(
  tokenId: string,
  lastUsedAt: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(apiTokens)
    .set({ lastUsedAt, updatedAt: lastUsedAt })
    .where(eq(apiTokens.id, tokenId))
    .run();
}

/**
 * Personal API tokens for scripts and CI. The secret is returned once, at creation.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, hashToken
 */
import { emit, subscribe } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import { createApiTokenSchema } from "@/schemas/api-token";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { hasRoleAtLeast } from "@/types/member";
import { actorEnvelope, orgResource, requireFound } from "./_support";
import { resolveActor } from "./member-service";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";
import type { ApiToken } from "@/types/api-token";

/** How many usable tokens one user may hold in one organization. */
const MAX_USABLE_TOKENS = 5;

const DAY_MS = 24 * 60 * 60 * 1000;

/** Public prefix length, including the `tfk_` marker. */
const PREFIX_LENGTH = 12;

export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);

  if (parsed.scope === "write") {
    assertCan(actor, "api_token:write", orgResource(parsed.orgId));
  }

  const now = new Date();
  const createdAt = toIsoTimestamp(now);
  const usable = await apiTokenRepo.countUsableApiTokens(
    parsed.orgId,
    actor.userId,
    createdAt,
  );
  if (usable >= MAX_USABLE_TOKENS) {
    throw new Error(
      `A user may hold at most ${MAX_USABLE_TOKENS} usable API tokens in an organization`,
    );
  }

  const token = `tfk_${randomToken()}`;
  const expiresAt = toIsoTimestamp(
    new Date(now.getTime() + parsed.expiresInDays * DAY_MS),
  );

  const apiToken = await apiTokenRepo.insertApiToken({
    orgId: parsed.orgId,
    userId: actor.userId,
    name: parsed.name,
    scope: parsed.scope,
    tokenHash: hashToken(token),
    prefix: token.slice(0, PREFIX_LENGTH),
    expiresAt,
    createdAt,
  });

  await emit("api_token.created", {
    ...actorEnvelope(actor),
    tokenId: apiToken.id,
    name: apiToken.name,
    scope: apiToken.scope,
  });

  return { token, apiToken };
}

export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId: UserId = actor.userId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);
  if (userId !== actor.userId) {
    assertCan(actor, "api_token:administer", orgResource(orgId));
  }
  return apiTokenRepo.listApiTokensForUser(orgId, userId);
}

export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);

  const existing = requireFound(
    await apiTokenRepo.findApiTokenById(orgId, tokenId),
    "ApiToken",
    tokenId,
  );

  if (existing.userId !== actor.userId) {
    assertCan(actor, "api_token:administer", orgResource(orgId));
  }

  if (existing.revokedAt !== null) return existing;

  const revokedAt = toIsoTimestamp(new Date());
  const revoked = requireFound(
    await apiTokenRepo.revokeApiTokenRow(orgId, tokenId, revokedAt),
    "ApiToken",
    tokenId,
  );

  await emit("api_token.revoked", {
    ...actorEnvelope(actor),
    tokenId: revoked.id,
  });

  return revoked;
}

/**
 * Resolves a raw `tfk_` secret to the actor it currently acts as.
 * Unknown, revoked, expired, or orphaned tokens resolve to `null` and leave
 * the row untouched. A hit records `lastUsedAt`.
 */
export async function authenticateApiToken(token: string): Promise<Actor | null> {
  const apiToken = await apiTokenRepo.findApiTokenByHash(hashToken(token));
  if (!apiToken) return null;
  if (apiToken.revokedAt !== null) return null;

  const now = toIsoTimestamp(new Date());
  if (apiToken.expiresAt <= now) return null;

  const org = await orgRepo.findOrgById(apiToken.orgId);
  if (!org || org.archivedAt !== null) return null;

  const member = await resolveActor(apiToken.userId, apiToken.orgId);
  if (!member) return null;

  await apiTokenRepo.touchApiTokenLastUsed(apiToken.id, now);

  if (apiToken.scope === "read") {
    return { userId: apiToken.userId, orgId: apiToken.orgId, role: "viewer" };
  }

  return { userId: member.userId, orgId: member.orgId, role: member.role };
}

/**
 * Revokes every still-live token the removed member holds in that organization
 * and audits each one with the remover as actor. Already-revoked rows and
 * tokens in other organizations are left alone.
 */
export function registerApiTokenListeners(): Unsubscribe {
  return subscribe("member.removed", async (payload) => {
    const live = await apiTokenRepo.listUnrevokedApiTokens(
      payload.orgId,
      payload.userId,
    );
    const revokedAt = toIsoTimestamp(new Date());

    for (const token of live) {
      const revoked = await apiTokenRepo.revokeApiTokenRow(
        payload.orgId,
        token.id,
        revokedAt,
      );
      if (!revoked || revoked.revokedAt !== revokedAt) continue;

      await emit("api_token.revoked", {
        orgId: payload.orgId,
        actorId: payload.actorId,
        occurredAt: revokedAt,
        tokenId: token.id,
      });
    }
  });
}

